package ingest
import("context";"crypto/sha256";"encoding/base64";"encoding/hex";"os";"path/filepath";"testing";"time";"ndweather/backend/internal/store")
func TestUtilities(t *testing.T){if _,e:=ParseTime("bad");e==nil{t.Fatal("bad time accepted")};png:=[]byte("\x89PNG\r\n\x1a\nrest");sum:=sha256.Sum256(png);a:=Asset{Encoding:"base64",ContentType:"image/png",Payload:base64.StdEncoding.EncodeToString(png),OriginalSize:len(png),SHA256:hex.EncodeToString(sum[:])};if _,e:=DecodeAsset(a,100);e!=nil{t.Fatal(e)};a.SHA256="bad";if _,e:=DecodeAsset(a,100);e==nil{t.Fatal("bad digest accepted")};if filepath.Ext(SafeName("../../x","image/png"))!=".png"{t.Fatal("unsafe name")};now:=time.Now();if IsStale(now,now,20)!="normal"||IsStale(now.Add(-21*time.Minute),now,20)!="stale"{t.Fatal("freshness")};if !RetentionCutoff(now,30).Before(now){t.Fatal("retention")}}
func TestProcessIdempotentAndRollback(t *testing.T){dir:=t.TempDir();sites:=filepath.Join(dir,"sites.yaml");os.WriteFile(sites,[]byte("- code: SAMPLE\n  name: Sample\n  latitude: 1\n  longitude: 1\n  forecastGridX: 1\n  forecastGridY: 1\n  warningAreaCodes: []\n  displayOrder: 1\n  enabled: true\n"),0600);s,e:=store.Open(filepath.Join(dir,"w.db"),sites);if e!=nil{t.Fatal(e)};defer s.DB.Close();svc:=Service{Store:s,AssetDir:filepath.Join(dir,"assets"),MaxAssetBytes:100};now:=time.Now().UTC().Format(time.RFC3339);temp:=2.0;b:=Batch{SchemaVersion:"1.0",BatchID:"WEATHER-TEST-0001",Source:"test",CreatedAt:now};b.Records.Observations=[]Observation{{SiteCode:"SAMPLE",ObservedAt:now,Temperature:&temp}};r,e:=svc.Process(context.Background(),b);if e!=nil||r.Observations!=1{t.Fatal(e)};r,e=svc.Process(context.Background(),b);if e!=nil||!r.Duplicate{t.Fatal("not idempotent")};bad:=b;bad.BatchID="WEATHER-TEST-0002";bad.Records.Observations[0].SiteCode="MISSING";if _,e=svc.Process(context.Background(),bad);e==nil{t.Fatal("expected FK rollback")};var n int;s.DB.QueryRow("SELECT count(*) FROM ingest_batches").Scan(&n);if n!=1{t.Fatalf("rollback failed %d",n)}}
